1	import type { NextRequest } from 'next/server'
2	import { NextResponse } from 'next/server'
3	import { z } from 'zod'
4	import { getAuthenticatedUser } from '@/lib/supabase/server'
5	import { createClient } from '@/lib/supabase/server'
6	import { authedRatelimit } from '@/lib/rate-limit'
7	import { logger } from '@/lib/logger'
8	import type { Database } from '@/lib/supabase/types'
9	
10	type BookingUpdate = Database['public']['Tables']['bookings']['Update']
11	
12	const UpdateBookingSchema = z.object({
13	  artist_id: z.string().uuid().optional(),
14	  service_id: z.string().uuid().nullable().optional(),
15	  location_id: z.string().uuid().nullable().optional(),
16	  scheduled_at: z.string().datetime().optional(),
17	  duration_min: z.number().int().min(15).max(480).optional(),
18	  price_cents: z.number().int().min(0).optional(),
19	  deposit_cents: z.number().int().min(0).optional(),
20	  notes: z.string().max(2000).nullable().optional(),
21	  client_notes: z.string().max(2000).nullable().optional(),
22	})
23	
24	interface Params {
25	  params: Promise<{ id: string }>
26	}
27	
28	export async function GET(_request: NextRequest, { params }: Params) {
29	  const authUser = await getAuthenticatedUser()
30	  if (!authUser) {
31	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
32	  }
33	
34	  const { success } = await authedRatelimit.limit(authUser.user.id)
35	  if (!success) {
36	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
37	  }
38	
39	  const { id } = await params
40	  if (!z.string().uuid().safeParse(id).success) {
41	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
42	  }
43	
44	  try {
45	    const supabase = await createClient()
46	    const { data, error } = await supabase
47	      .from('bookings')
48	      .select(
49	        `
50	        *,
51	        client:clients(id, first_name, last_name, email, phone, total_sessions, total_spent_cents, tags, notes),
52	        artist:artists(id, display_name, avatar_url, sort_order),
53	        service:services(id, name, duration_min, base_price_cents, deposit_cents, color),
54	        location:locations(id, name, address, city),
55	        photos:booking_photos(id, kind, caption, taken_at, storage_path)
56	      `
57	      )
58	      .eq('id', id)
59	      .eq('studio_id', authUser.studioId)
60	      .single()
61	
62	    if (error || !data) {
63	      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
64	    }
65	
66	    return NextResponse.json({ data })
67	  } catch (err) {
68	    logger.error({ err, bookingId: id }, 'booking GET unexpected error')
69	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
70	  }
71	}
72	
73	export async function PATCH(request: NextRequest, { params }: Params) {
74	  const authUser = await getAuthenticatedUser()
75	  if (!authUser) {
76	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
77	  }
78	
79	  const { success } = await authedRatelimit.limit(authUser.user.id)
80	  if (!success) {
81	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
82	  }
83	
84	  const { id } = await params
85	  if (!z.string().uuid().safeParse(id).success) {
86	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
87	  }
88	
89	  let body: unknown
90	  try {
91	    body = await request.json()
92	  } catch {
93	    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
94	  }
95	
96	  const parsed = UpdateBookingSchema.safeParse(body)
97	  if (!parsed.success) {
98	    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
99	  }
100	
101	  if (Object.keys(parsed.data).length === 0) {
102	    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
103	  }
104	
105	  try {
106	    const supabase = await createClient()
107	    // Strip undefined values — required for exactOptionalPropertyTypes + Supabase update
108	    const updates = Object.fromEntries(
109	      Object.entries(parsed.data).filter(([, v]) => v !== undefined)
110	    ) as BookingUpdate
111	    const { data, error } = await supabase
112	      .from('bookings')
113	      .update(updates)
114	      .eq('id', id)
115	      .eq('studio_id', authUser.studioId)
116	      .select('id, scheduled_at, end_at, duration_min, status, price_cents, notes, updated_at')
117	      .single()
118	
119	    if (error) {
120	      if (error.code === '23P01') {
121	        return NextResponse.json(
122	          { error: 'That time slot is already booked for this artist' },
123	          { status: 409 }
124	        )
125	      }
126	      if (error.code === 'PGRST116') {
127	        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
128	      }
129	      logger.error({ err: error, bookingId: id }, 'booking PATCH failed')
130	      return NextResponse.json({ error: 'Failed to update booking' }, { status: 500 })
131	    }
132	
133	    return NextResponse.json({ data })
134	  } catch (err) {
135	    logger.error({ err, bookingId: id }, 'booking PATCH unexpected error')
136	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
137	  }
138	}
139	
140	export async function DELETE(_request: NextRequest, { params }: Params) {
141	  const authUser = await getAuthenticatedUser()
142	  if (!authUser) {
143	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
144	  }
145	
146	  const { success } = await authedRatelimit.limit(authUser.user.id)
147	  if (!success) {
148	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
149	  }
150	
151	  const { id } = await params
152	  if (!z.string().uuid().safeParse(id).success) {
153	    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
154	  }
155	
156	  try {
157	    const supabase = await createClient()
158	    const { error } = await supabase
159	      .from('bookings')
160	      .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
161	      .eq('id', id)
162	      .eq('studio_id', authUser.studioId)
163	
164	    if (error) {
165	      if (error.code === 'PGRST116') {
166	        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
167	      }
168	      logger.error({ err: error, bookingId: id }, 'booking DELETE failed')
169	      return NextResponse.json({ error: 'Failed to cancel booking' }, { status: 500 })
170	    }
171	
172	    return new NextResponse(null, { status: 204 })
173	  } catch (err) {
174	    logger.error({ err, bookingId: id }, 'booking DELETE unexpected error')
175	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
176	  }
177	}
